window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["spotify"]={html:"<div class=\"own-spotify\">\n  <!-- ── TOP BAR ─────────────────────────────────────────────────────── -->\n  <header class=\"sp-top\">\n    <a class=\"sp-brand\" href=\"#sp-top\" aria-label=\"Northwind home\">\n      <span class=\"sp-logo\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"11\"/><path d=\"M6.5 9.6c3.6-1 7.6-.6 10.8 1.2M7.2 12.8c3-.8 6.2-.4 8.8 1.1M8 15.8c2.4-.6 4.9-.3 7 .9\" fill=\"none\" stroke=\"#121212\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg>\n      </span>\n      Northwind\n    </a>\n    <div class=\"sp-top-actions\">\n      <a class=\"sp-pill sp-pill-outline\" href=\"#\">Upgrade</a>\n      <button class=\"sp-circle\" type=\"button\" aria-label=\"Account\"><span class=\"sp-avatar\">FL</span></button>\n    </div>\n  </header>\n\n  <div class=\"sp-shell\">\n    <!-- ── SIDEBAR ───────────────────────────────────────────────────── -->\n    <aside class=\"sp-side\" aria-label=\"Navigation\">\n      <nav class=\"sp-side-group\">\n        <a class=\"sp-nav on\" href=\"#sp-dash\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 11 12 4l8 7M6 10v9h12v-9\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/></svg>Dashboards</a>\n        <a class=\"sp-nav\" href=\"#sp-regions\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><path d=\"M4 12h16M12 4c2.5 3 2.5 13 0 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/></svg>Regions</a>\n        <a class=\"sp-nav\" href=\"#sp-alerts\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 10a6 6 0 0 1 12 0v4l2 3H4l2-3z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/><path d=\"M10 20a2 2 0 0 0 4 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/></svg>Alerts</a>\n      </nav>\n      <div class=\"sp-side-group\">\n        <span class=\"sp-side-title\">Your floor</span>\n        <a class=\"sp-nav sp-nav-sm\" href=\"#\"><span class=\"sp-dot\" style=\"--c:#1ed760\"></span>Luzon</a>\n        <a class=\"sp-nav sp-nav-sm\" href=\"#\"><span class=\"sp-dot\" style=\"--c:#539df5\"></span>Visayas</a>\n        <a class=\"sp-nav sp-nav-sm\" href=\"#\"><span class=\"sp-dot\" style=\"--c:#ffa42b\"></span>Mindanao</a>\n        <a class=\"sp-nav sp-nav-sm\" href=\"#\"><span class=\"sp-dot\" style=\"--c:#f3727f\"></span>Singapore</a>\n      </div>\n    </aside>\n\n    <!-- ── MAIN ──────────────────────────────────────────────────────── -->\n    <main id=\"sp-top\" class=\"sp-main\">\n      <!-- hero -->\n      <section id=\"sp-dash\" class=\"sp-hero\" aria-labelledby=\"sp-h1\">\n        <div class=\"sp-hero-copy\">\n          <p class=\"sp-eyebrow\">Operations analytics</p>\n          <h1 id=\"sp-h1\" class=\"sp-title\">Good evening</h1>\n          <p class=\"sp-sub\">Your regions are live. Pick up where the floor left off.</p>\n          <div class=\"sp-hero-cta\">\n            <a class=\"sp-pill sp-pill-green\" href=\"#sp-regions\"><span class=\"sp-play\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M8 5v14l11-7z\"/></svg></span>Open dashboards</a>\n            <a class=\"sp-pill sp-pill-dark\" href=\"#sp-alerts\">View alerts</a>\n          </div>\n        </div>\n      </section>\n\n      <!-- recent tiles -->\n      <section class=\"sp-sec\" aria-labelledby=\"sp-recent-h\">\n        <div class=\"sp-sec-head\"><h2 id=\"sp-recent-h\" class=\"sp-sec-title\">Jump back in</h2><a class=\"sp-see\" href=\"#\">Show all</a></div>\n        <div class=\"sp-tiles\" id=\"spTileGrid\"></div>\n      </section>\n\n      <!-- region cards -->\n      <section id=\"sp-regions\" class=\"sp-sec\" aria-labelledby=\"sp-regions-h\">\n        <div class=\"sp-sec-head\"><h2 id=\"sp-regions-h\" class=\"sp-sec-title\">Regions on the floor</h2><a class=\"sp-see\" href=\"#\">All 42</a></div>\n        <div class=\"sp-cards\" id=\"spRegionGrid\"></div>\n      </section>\n\n      <!-- alerts -->\n      <section id=\"sp-alerts\" class=\"sp-sec\" aria-labelledby=\"sp-alerts-h\">\n        <div class=\"sp-sec-head\"><h2 id=\"sp-alerts-h\" class=\"sp-sec-title\">Today's alerts</h2></div>\n        <div class=\"sp-alert-list\" id=\"spAlertList\"></div>\n      </section>\n    </main>\n  </div>\n\n  <!-- ── NOW PLAYING BAR ────────────────────────────────────────────── -->\n  <div class=\"sp-now\" aria-label=\"Current region\">\n    <div class=\"sp-now-left\">\n      <span class=\"sp-now-art\" aria-hidden=\"true\"></span>\n      <span class=\"sp-now-meta\"><b id=\"spNowName\">Luzon</b><span id=\"spNowSub\">throughput · live</span></span>\n    </div>\n    <div class=\"sp-now-mid\">\n      <div class=\"sp-now-controls\">\n        <button class=\"sp-ctrl\" type=\"button\" aria-label=\"Previous\">&#9198;</button>\n        <button class=\"sp-ctrl sp-ctrl-play\" type=\"button\" aria-label=\"Play\"><svg viewBox=\"0 0 24 24\"><path d=\"M8 5v14l11-7z\"/></svg></button>\n        <button class=\"sp-ctrl\" type=\"button\" aria-label=\"Next\">&#9197;</button>\n      </div>\n      <div class=\"sp-now-bar\"><span class=\"sp-now-progress\" id=\"spNowProgress\"></span></div>\n    </div>\n    <div class=\"sp-now-right\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M4 12h3l2-6 3 12 3-9 2 3h3\" fill=\"none\" stroke=\"#1ed760\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n      <span class=\"sp-now-val\" id=\"spNowVal\">3,987/hr</span>\n    </div>\n  </div>\n\n  <!-- ── FOOTER ──────────────────────────────────────────────────────── -->\n  <footer class=\"sp-footer\">\n    <div class=\"sp-foot-grid\">\n      <div class=\"sp-foot-brand\"><span class=\"sp-foot-logo\">Northwind</span><p class=\"sp-caption\">Sample data — showcase only</p></div>\n      <div class=\"sp-foot-col\"><h3>Product</h3><a href=\"#\">Dashboards</a><a href=\"#\">Regions</a><a href=\"#\">Alerts</a></div>\n      <div class=\"sp-foot-col\"><h3>Developers</h3><a href=\"#\">API</a><a href=\"#\">Docs</a><a href=\"#\">Status</a></div>\n      <div class=\"sp-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"sp-foot-row\"><span>© 2026 Northwind</span><span>Made for operations teams</span></div>\n  </footer>\n</div>\n",css:"/* ══ SPOTIFY — own layout for showcase.html ══════════════════════════════\n   An immersive dark player shell: near-black surfaces, achromatic UI, Spotify\n   Green for functional highlights only, pill/circle geometry, uppercase button\n   labels with wide tracking, and heavy shadows. The UI stays achromatic and\n   colour comes from the region \"artwork\" tiles. Scoped under `.own-spotify`. */\n\n.own-spotify {\n  --base: #121212;\n  --surface: #181818;\n  --mid: #1f1f1f;\n  --card: #252525;\n  --white: #ffffff;\n  --silver: #b3b3b3;\n  --near: #cbcbcb;\n  --green: #1ed760;\n  --green-dark: #1db954;\n  --border: #4d4d4d;\n  --light-border: #7c7c7c;\n  --red: #f3727f;\n  --orange: #ffa42b;\n  --blue: #539df5;\n  --shadow-heavy: rgba(0,0,0,.5) 0 8px 24px;\n  --shadow-med: rgba(0,0,0,.3) 0 8px 8px;\n\n  --f-title: 'SpotifyMixUITitle', 'Inter', Helvetica, Arial, sans-serif;\n  --f-ui: 'SpotifyMixUI', 'Inter', Helvetica, Arial, sans-serif;\n\n  --gut: clamp(16px, 3cqi, 24px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--base);\n  color: var(--white);\n  font-family: var(--f-ui);\n  font-size: 14px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-spotify *, .own-spotify *::before, .own-spotify *::after { box-sizing: border-box; }\n.own-spotify :focus-visible { outline: 2px solid var(--green); outline-offset: 3px; border-radius: 4px; }\n.own-spotify .sp-caption { font-size: 12px; color: var(--silver); }\n.own-spotify .sp-title { font-family: var(--f-title); font-weight: 700; font-size: clamp(30px, 4.6cqi, 48px); line-height: 1.1; margin: 0; }\n.own-spotify .sp-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: 1.4px; text-transform: uppercase; color: var(--green); margin: 0 0 12px; }\n.own-spotify .sp-sub { margin: 12px 0 26px; color: var(--silver); font-size: 16px; }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-spotify .sp-pill {\n  display: inline-flex; align-items: center; gap: 10px; justify-content: center;\n  height: 44px; padding: 0 20px; border-radius: 9999px;\n  font-family: var(--f-ui); font-size: 14px; font-weight: 700; letter-spacing: 1.4px; text-transform: uppercase;\n  transition: background-color .2s, transform .2s, color .2s;\n  white-space: nowrap;\n}\n.own-spotify .sp-pill:hover { transform: scale(1.03); }\n.own-spotify .sp-pill-green { background: var(--green); color: #000; }\n.own-spotify .sp-pill-green:hover { background: #22e26a; }\n.own-spotify .sp-pill-dark { background: var(--mid); color: #fff; }\n.own-spotify .sp-pill-dark:hover { background: #2a2a2a; }\n.own-spotify .sp-pill-outline { background: transparent; color: #fff; border: 1px solid var(--light-border); }\n.own-spotify .sp-pill-outline:hover { border-color: #fff; }\n.own-spotify .sp-play { display: grid; place-items: center; width: 20px; height: 20px; }\n.own-spotify .sp-play svg { width: 18px; height: 18px; fill: #000; }\n.own-spotify .sp-circle { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; background: var(--mid); border: 0; cursor: pointer; }\n.own-spotify .sp-avatar { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: #4f4f4f; color: #fff; font-size: 12px; font-weight: 700; }\n\n/* ── top bar ─────────────────────────────────────────────────────────── */\n.own-spotify .sp-top { display: flex; align-items: center; gap: 20px; height: 64px; padding: 0 var(--gut, 24px); background: var(--base); }\n.own-spotify .sp-brand { display: inline-flex; align-items: center; gap: 10px; font-family: var(--f-title); font-weight: 700; font-size: 18px; color: #fff; }\n.own-spotify .sp-logo { width: 26px; height: 26px; }\n.own-spotify .sp-logo svg { width: 26px; height: 26px; }\n.own-spotify .sp-logo circle { fill: var(--green); }\n.own-spotify .sp-top-actions { margin-left: auto; display: flex; align-items: center; gap: 12px; }\n.own-spotify .sp-top-actions .sp-pill { height: 40px; font-size: 13px; }\n\n/* ── shell ───────────────────────────────────────────────────────────── */\n.own-spotify .sp-shell { display: grid; grid-template-columns: 240px 1fr; gap: 8px; padding: 0 8px 8px; }\n.own-spotify .sp-side { background: var(--surface); border-radius: 8px; padding: 16px 10px; position: sticky; top: 132px; align-self: start; }\n.own-spotify .sp-side-group { display: grid; gap: 2px; padding: 8px 4px; }\n.own-spotify .sp-side-group + .sp-side-group { margin-top: 12px; border-top: 1px solid #2a2a2a; padding-top: 16px; }\n.own-spotify .sp-side-title { font-size: 12px; font-weight: 700; letter-spacing: 0.5px; color: var(--silver); padding: 0 10px 8px; }\n.own-spotify .sp-nav { display: flex; align-items: center; gap: 14px; padding: 9px 10px; border-radius: 4px; color: var(--silver); font-size: 14px; font-weight: 400; transition: color .15s, background-color .15s; }\n.own-spotify .sp-nav:hover { color: #fff; }\n.own-spotify .sp-nav.on { color: #fff; font-weight: 700; }\n.own-spotify .sp-nav svg { width: 22px; height: 22px; flex: none; }\n.own-spotify .sp-nav-sm { font-size: 13px; }\n.own-spotify .sp-dot { width: 10px; height: 10px; border-radius: 2px; background: var(--c, var(--green)); flex: none; }\n\n/* ── main ────────────────────────────────────────────────────────────── */\n.own-spotify .sp-main { background: linear-gradient(180deg, #1c1c1c 0%, var(--base) 320px); border-radius: 8px; padding: 0 0 24px; min-width: 0; }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-spotify .sp-hero { padding: 40px clamp(20px, 4cqi, 40px) 32px; background: radial-gradient(120% 130% at 12% 0%, rgba(30,215,96,.16), transparent 56%); }\n.own-spotify .sp-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }\n\n/* ── sections ────────────────────────────────────────────────────────── */\n.own-spotify .sp-sec { padding: 8px clamp(20px, 4cqi, 40px) 24px; }\n.own-spotify .sp-sec-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; margin-bottom: 18px; }\n.own-spotify .sp-sec-title { font-family: var(--f-title); font-weight: 700; font-size: 24px; margin: 0; }\n.own-spotify .sp-see { font-size: 12px; font-weight: 700; letter-spacing: 0.5px; text-transform: uppercase; color: var(--silver); }\n.own-spotify .sp-see:hover { color: #fff; text-decoration: underline; }\n\n/* ── tiles (artwork) ─────────────────────────────────────────────────── */\n.own-spotify .sp-tiles { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }\n.own-spotify .sp-tile { position: relative; display: flex; align-items: center; gap: 14px; background: var(--mid); border-radius: 6px; overflow: hidden; padding-right: 12px; transition: background-color .2s; }\n.own-spotify .sp-tile:hover { background: #2c2c2c; }\n.own-spotify .sp-tile-art { width: 72px; height: 72px; flex: none; background: linear-gradient(135deg, var(--c1), var(--c2)); }\n.own-spotify .sp-tile-text { display: flex; flex-direction: column; }\n.own-spotify .sp-tile-name { font-weight: 700; font-size: 15px; }\n.own-spotify .sp-tile-meta { font-size: 12px; color: var(--silver); }\n.own-spotify .sp-tile-play { position: absolute; right: 12px; bottom: 12px; width: 44px; height: 44px; border-radius: 50%; background: var(--green); display: grid; place-items: center; opacity: 0; transform: translateY(6px); transition: opacity .2s, transform .2s; box-shadow: var(--shadow-med); }\n.own-spotify .sp-tile:hover .sp-tile-play { opacity: 1; transform: none; }\n.own-spotify .sp-tile-play svg { width: 20px; height: 20px; fill: #000; margin-left: 2px; }\n\n/* ── region cards ────────────────────────────────────────────────────── */\n.own-spotify .sp-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 16px; }\n.own-spotify .sp-card { background: var(--surface); border-radius: 8px; padding: 16px; transition: background-color .2s; }\n.own-spotify .sp-card:hover { background: var(--card); }\n.own-spotify .sp-card-art { aspect-ratio: 1; border-radius: 6px; background: linear-gradient(140deg, var(--c1), var(--c2)); margin-bottom: 14px; position: relative; overflow: hidden; box-shadow: var(--shadow-med); }\n.own-spotify .sp-card-art::after { content: ''; position: absolute; inset: 0; background-image: linear-gradient(rgba(255,255,255,.06) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.06) 1px, transparent 1px); background-size: 22px 22px; }\n.own-spotify .sp-card-name { font-weight: 700; font-size: 15px; }\n.own-spotify .sp-card-meta { font-size: 13px; color: var(--silver); margin-top: 4px; }\n.own-spotify .sp-card-stat { font-size: 13px; color: var(--green); font-weight: 700; margin-top: 8px; }\n\n/* ── alerts ──────────────────────────────────────────────────────────── */\n.own-spotify .sp-alert-list { display: grid; gap: 4px; }\n.own-spotify .sp-alert { display: grid; grid-template-columns: 40px 1fr auto; gap: 16px; align-items: center; padding: 12px 16px; border-radius: 6px; transition: background-color .15s; }\n.own-spotify .sp-alert:hover { background: var(--mid); }\n.own-spotify .sp-alert-ic { width: 40px; height: 40px; border-radius: 6px; display: grid; place-items: center; background: var(--mid); color: var(--c, var(--orange)); font-weight: 700; }\n.own-spotify .sp-alert-title { font-weight: 700; font-size: 14px; }\n.own-spotify .sp-alert-meta { font-size: 12px; color: var(--silver); margin-top: 2px; }\n.own-spotify .sp-alert-tag { font-size: 10.5px; font-weight: 600; text-transform: capitalize; color: var(--c, var(--orange)); border: 1px solid currentColor; border-radius: 9999px; padding: 3px 10px; }\n\n/* ── now playing bar ─────────────────────────────────────────────────── */\n.own-spotify .sp-now {\n  position: sticky; bottom: 0; z-index: 38;\n  display: grid; grid-template-columns: 1fr 1.4fr 1fr; align-items: center; gap: 16px;\n  padding: 10px clamp(16px, 3cqi, 24px);\n  background: rgba(24,24,24,.96); backdrop-filter: blur(10px);\n  border-top: 1px solid #2a2a2a;\n}\n.own-spotify .sp-now-left { display: flex; align-items: center; gap: 12px; min-width: 0; }\n.own-spotify .sp-now-art { width: 48px; height: 48px; border-radius: 4px; flex: none; background: linear-gradient(135deg, #1ed760, #539df5); }\n.own-spotify .sp-now-meta { display: flex; flex-direction: column; min-width: 0; }\n.own-spotify .sp-now-meta b { font-size: 14px; font-weight: 700; }\n.own-spotify .sp-now-meta span { font-size: 12px; color: var(--silver); }\n.own-spotify .sp-now-mid { display: grid; gap: 8px; }\n.own-spotify .sp-now-controls { display: flex; align-items: center; justify-content: center; gap: 18px; }\n.own-spotify .sp-ctrl { background: none; border: 0; color: var(--silver); font-size: 16px; cursor: pointer; line-height: 1; }\n.own-spotify .sp-ctrl:hover { color: #fff; }\n.own-spotify .sp-ctrl-play { width: 36px; height: 36px; border-radius: 50%; background: #fff; display: grid; place-items: center; }\n.own-spotify .sp-ctrl-play svg { width: 16px; height: 16px; fill: #000; margin-left: 2px; }\n.own-spotify .sp-now-bar { height: 4px; border-radius: 2px; background: #4d4d4d; overflow: hidden; }\n.own-spotify .sp-now-progress { display: block; height: 100%; width: 42%; background: var(--green); border-radius: 2px; transition: width .6s ease; }\n.own-spotify .sp-now-right { display: flex; align-items: center; justify-content: flex-end; gap: 10px; color: var(--silver); }\n.own-spotify .sp-now-right svg { width: 20px; height: 20px; }\n.own-spotify .sp-now-val { font-size: 13px; font-variant-numeric: tabular-nums; color: #fff; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-spotify .sp-footer { background: var(--base); padding: clamp(32px, 4cqi, 56px) clamp(20px, 4cqi, 40px) 24px; border-top: 1px solid #2a2a2a; }\n.own-spotify .sp-foot-grid { display: grid; grid-template-columns: 1.5fr repeat(3, 1fr); gap: 28px; }\n.own-spotify .sp-foot-logo { font-family: var(--f-title); font-weight: 700; font-size: 18px; color: #fff; display: block; margin-bottom: 10px; }\n.own-spotify .sp-foot-col { display: flex; flex-direction: column; gap: 12px; }\n.own-spotify .sp-foot-col h3 { margin: 0 0 4px; font-size: 14px; font-weight: 700; color: #fff; }\n.own-spotify .sp-foot-col a { color: var(--silver); font-size: 14px; }\n.own-spotify .sp-foot-col a:hover { color: #fff; text-decoration: underline; }\n.own-spotify .sp-foot-row { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 36px; padding-top: 20px; border-top: 1px solid #2a2a2a; font-size: 12px; color: var(--silver); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-spotify .sp-tiles { grid-template-columns: repeat(2, 1fr); }\n  .own-spotify .sp-foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-spotify .sp-shell { grid-template-columns: 1fr; }\n  .own-spotify .sp-side { position: static; }\n  .own-spotify .sp-side-group { display: flex; flex-wrap: wrap; gap: 4px; }\n  .own-spotify .sp-side-group + .sp-side-group { border-top: none; margin-top: 8px; padding-top: 4px; }\n  .own-spotify .sp-side-title { width: 100%; }\n  .own-spotify .sp-now { grid-template-columns: 1fr auto; }\n  .own-spotify .sp-now-right { display: none; }\n}\n@container frame (max-width: 430px) {\n  .own-spotify .sp-tiles { grid-template-columns: 1fr; }\n  .own-spotify .sp-foot-grid { grid-template-columns: 1fr; }\n  .own-spotify .sp-now-mid { display: none; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-spotify *, .own-spotify *::before, .own-spotify *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ SPOTIFY — own layout behaviour for showcase.html ═════════════════════
   Registers window.OWN_LAYOUTS['spotify'].init(root). Renders the jump-back
   tiles, region cards, alerts and wires the now-playing bar, rotating through
   regions. Returns a cleanup fn (clears timers, listeners, rAF). */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var TILES = [
    { name: 'Luzon throughput', meta: 'Regional dashboard', c1: '#1ed760', c2: '#0a5c2c' },
    { name: 'Visayas yield', meta: 'Site roll-up', c1: '#539df5', c2: '#123a63' },
    { name: 'Mindanao cost', meta: 'Cost per case', c1: '#ffa42b', c2: '#6b3f00' },
    { name: 'Forecast Q4', meta: 'Projection model', c1: '#f3727f', c2: '#6b1f28' }
  ];

  var REGIONS = [
    { name: 'Luzon', meta: 'Manufacturing · 8 sites', stat: '3,987/hr', c1: '#1ed760', c2: '#0a5c2c' },
    { name: 'Visayas', meta: 'Logistics · 5 sites', stat: '2,244/hr', c1: '#539df5', c2: '#123a63' },
    { name: 'Mindanao', meta: 'Agri ops · 6 sites', stat: '1,602/hr', c1: '#ffa42b', c2: '#6b3f00' },
    { name: 'Singapore', meta: 'Distribution · 3 sites', stat: '3,020/hr', c1: '#f3727f', c2: '#6b1f28' },
    { name: 'Sydney', meta: 'Fulfilment · 4 sites', stat: '2,870/hr', c1: '#1db954', c2: '#0b3d20' }
  ];

  var ALERTS = [
    { title: 'Luzon under target by 5.1%', meta: 'Throughput · 12 minutes ago', tag: 'warning', c: '#ffa42b', ic: '!' },
    { title: 'Visayas above target by 6.9%', meta: 'Throughput · 40 minutes ago', tag: 'good', c: '#1ed760', ic: '\u2191' },
    { title: 'Mindanao cost per case +3%', meta: 'Cost · 2 hours ago', tag: 'info', c: '#539df5', ic: 'i' },
    { title: 'Singapore pipeline degraded', meta: 'Latency · 3 hours ago', tag: 'critical', c: '#f3727f', ic: '\u2715' }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function $(root, sel) { return root.querySelector(sel); }

  OWN['spotify'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var timers = [];
      var rafs = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function later(fn, ms) { var id = window.setTimeout(fn, ms); timers.push(id); return id; }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }

      var tiles = $('#spTileGrid', root);
      if (tiles) tiles.innerHTML = TILES.map(function (t) {
        return '<a class="sp-tile" href="#" style="--c1:' + t.c1 + ';--c2:' + t.c2 + '">'
          + '<span class="sp-tile-art" aria-hidden="true"></span>'
          + '<span class="sp-tile-text"><span class="sp-tile-name">' + esc(t.name) + '</span>'
          + '<span class="sp-tile-meta">' + esc(t.meta) + '</span></span>'
          + '<span class="sp-tile-play" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></span></a>';
      }).join('');

      var cards = $('#spRegionGrid', root);
      if (cards) cards.innerHTML = REGIONS.map(function (r) {
        return '<a class="sp-card" href="#" style="--c1:' + r.c1 + ';--c2:' + r.c2 + '">'
          + '<span class="sp-card-art" aria-hidden="true"></span>'
          + '<span class="sp-card-name">' + esc(r.name) + '</span>'
          + '<span class="sp-card-meta">' + esc(r.meta) + '</span>'
          + '<span class="sp-card-stat">' + esc(r.stat) + '</span></a>';
      }).join('');

      var alerts = $('#spAlertList', root);
      if (alerts) alerts.innerHTML = ALERTS.map(function (a) {
        return '<div class="sp-alert"><span class="sp-alert-ic" style="--c:' + a.c + '" aria-hidden="true">' + a.ic + '</span>'
          + '<span><span class="sp-alert-title">' + esc(a.title) + '</span>'
          + '<span class="sp-alert-meta">' + esc(a.meta) + '</span></span>'
          + '<span class="sp-alert-tag" style="--c:' + a.c + '">' + esc(a.tag) + '</span></div>';
      }).join('');

      /* now-playing bar cycles through regions */
      var nameEl = $('#spNowName', root);
      var subEl = $('#spNowSub', root);
      var valEl = $('#spNowVal', root);
      var progEl = $('#spNowProgress', root);
      var idx = 0;
      function show(i) {
        var r = REGIONS[i % REGIONS.length];
        if (nameEl) nameEl.textContent = r.name;
        if (subEl) subEl.textContent = 'throughput · live';
        if (valEl) valEl.textContent = r.stat;
        if (progEl) progEl.style.width = (30 + ((i * 37) % 55)) + '%';
      }
      if (!reduced && nameEl) {
        later(function tick() {
          if (disposed) return;
          idx = (idx + 1) % REGIONS.length;
          show(idx);
          later(tick, 3200);
        }, 3200);
      }

      Array.prototype.slice.call(root.querySelectorAll('a[href^="#"]')).forEach(function (a) {
        on(a, 'click', function (e) {
          var href = a.getAttribute('href');
          if (!href || href.length < 2) return;
          var target = root.querySelector(href);
          if (!target) return;
          e.preventDefault();
          target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
        });
      });

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        timers.forEach(function (id) { clearTimeout(id); });
      };
    }
  };
})();
